// every user-facing clear gets it: `entire doctor`, `entire reset`, and
// `entire reset <session>`.
func withLockWaitNotice(sessionID string, errW io.Writer, notifyAfter time.Duration, clear func() error) error {
	done := make(chan error, 1)
	go func() { done <- clear() }()

